/**
 * Recurring-issue rules. Every service read is filtered by `orgId`; the job's
 * sweep is cross-tenant on purpose, since no request drives it.
 */
import { and, asc, count, eq, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, recurringIssues } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { brandId } from "./_mappers";
import type { RecurringIssueRow } from "@/server/db/schema/recurring-issues";
import type {
  IsoTimestamp,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { IssuePriority } from "@/types/issue";
import type {
  RecurrenceCadence,
  RecurringIssue,
} from "@/types/recurring-issue";

/** Fields the service supplies when a rule is created. */
export type NewRecurringIssue = {
  orgId: OrgId;
  projectId: ProjectId;
  title: string;
  priority: IssuePriority;
  assigneeId: UserId | null;
  cadence: RecurrenceCadence;
  weekday: number | null;
  timezone: string;
  startsOn: string;
  createdBy: UserId;
};

function toRecurringIssue(row: RecurringIssueRow): RecurringIssue {
  return {
    id: row.id,
    orgId: brandId<OrgId>(row.orgId),
    projectId: brandId<ProjectId>(row.projectId),
    title: row.title,
    priority: row.priority,
    assigneeId: row.assigneeId === null ? null : brandId<UserId>(row.assigneeId),
    cadence: row.cadence,
    weekday: row.weekday,
    timezone: row.timezone,
    startsOn: row.startsOn,
    lastOccurrenceOn: row.lastOccurrenceOn,
    paused: row.paused,
    createdBy: brandId<UserId>(row.createdBy),
    createdAt: row.createdAt as IsoTimestamp,
    updatedAt: row.updatedAt as IsoTimestamp,
  };
}

/** Creation order; `rowid` breaks ties between rules stamped the same ms. */
const CREATION_ORDER = [asc(recurringIssues.createdAt), asc(sql`rowid`)];

export async function findRecurringIssueById(
  orgId: OrgId,
  recurringIssueId: string,
): Promise<RecurringIssue | null> {
  const row = getDb()
    .select()
    .from(recurringIssues)
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .get();
  return row ? toRecurringIssue(row) : null;
}

export async function listRecurringIssues(
  orgId: OrgId,
): Promise<readonly RecurringIssue[]> {
  return getDb()
    .select()
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .orderBy(...CREATION_ORDER)
    .all()
    .map(toRecurringIssue);
}

/** The `recurringIssues` quota compares against this; paused rules count. */
export async function countRecurringIssues(orgId: OrgId): Promise<number> {
  const row = getDb()
    .select({ value: count() })
    .from(recurringIssues)
    .where(orgPredicate(recurringIssues.orgId, orgId))
    .get();
  return row?.value ?? 0;
}

export async function insertRecurringIssue(
  input: NewRecurringIssue,
): Promise<RecurringIssue> {
  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(recurringIssues)
    .values({
      id: newId(),
      orgId: input.orgId,
      projectId: input.projectId,
      title: input.title,
      priority: input.priority,
      assigneeId: input.assigneeId,
      cadence: input.cadence,
      weekday: input.weekday,
      timezone: input.timezone,
      startsOn: input.startsOn,
      lastOccurrenceOn: null,
      paused: false,
      createdBy: input.createdBy,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();
  return toRecurringIssue(row);
}

async function patchRecurringIssue(
  orgId: OrgId,
  recurringIssueId: string,
  patch: { paused?: boolean; lastOccurrenceOn?: string },
): Promise<RecurringIssue> {
  const row = getDb()
    .update(recurringIssues)
    .set({ ...patch, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(recurringIssues.orgId, orgId),
        eq(recurringIssues.id, recurringIssueId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Recurring issue ${recurringIssueId} not found`);
  return toRecurringIssue(row);
}

export async function setRecurringIssuePaused(
  orgId: OrgId,
  recurringIssueId: string,
  paused: boolean,
): Promise<RecurringIssue> {
  return patchRecurringIssue(orgId, recurringIssueId, { paused });
}

export async function setLastOccurrence(
  orgId: OrgId,
  recurringIssueId: string,
  occurrenceOn: string,
): Promise<RecurringIssue> {
  return patchRecurringIssue(orgId, recurringIssueId, {
    lastOccurrenceOn: occurrenceOn,
  });
}

/**
 * The job's work list: every non-paused rule of every organization, in
 * creation order. Cross-tenant on purpose — see the module comment.
 */
export async function listActiveRecurringIssues(): Promise<
  readonly RecurringIssue[]
> {
  return getDb()
    .select()
    .from(recurringIssues)
    .where(eq(recurringIssues.paused, false))
    .orderBy(...CREATION_ORDER)
    .all()
    .map(toRecurringIssue);
}
