const MS_PER_DAY = 24 * 60 * 60 * 1000;

type DateParts = { year: number; month: number; day: number };

function parseDay(value: string): DateParts {
  const [year, month, day] = value.split("-").map(Number);
  return { year: year ?? 0, month: month ?? 1, day: day ?? 1 };
}

function pad(value: number, width: number): string {
  return String(value).padStart(width, "0");
}

function formatDay(date: Date): string {
  return `${pad(date.getUTCFullYear(), 4)}-${pad(date.getUTCMonth() + 1, 2)}-${pad(date.getUTCDate(), 2)}`;
}

function dayToUtc(value: string): Date {
  const { year, month, day } = parseDay(value);
  const date = new Date(Date.UTC(year, month - 1, day));
  date.setUTCFullYear(year);
  return date;
}

/** The calendar date (`YYYY-MM-DD`) the wall clock shows in `timeZone` at `at`. */
export function localDateIn(at: Date, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-US", {
    timeZone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    calendar: "gregory",
    numberingSystem: "latn",
  }).formatToParts(at);

  const pick = (type: Intl.DateTimeFormatPartTypes): number =>
    Number(parts.find((part) => part.type === type)?.value ?? NaN);

  return `${pad(pick("year"), 4)}-${pad(pick("month"), 2)}-${pad(pick("day"), 2)}`;
}

/** ISO weekday of a `YYYY-MM-DD` day: 1 = Monday … 7 = Sunday. */
export function isoWeekday(value: string): number {
  const sundayBased = dayToUtc(value).getUTCDay();
  return sundayBased === 0 ? 7 : sundayBased;
}

export function addDays(value: string, days: number): string {
  return formatDay(new Date(dayToUtc(value).getTime() + days * MS_PER_DAY));
}

export type RecurrenceRule = {
  readonly cadence: RecurrenceCadence;
  readonly weekday: number | null;
  readonly timezone: string;
  readonly startsOn: string;
};

/**
 * The latest occurrence day of `rule` that has started by `now`, or `null`
 * when none has (the rule starts in the future, locally).
 */
export function latestStartedOccurrence(
  rule: RecurrenceRule,
  now: Date,
): string | null {
  const today = localDateIn(now, rule.timezone);
  if (today < rule.startsOn) return null;

  if (rule.cadence === "daily") return today;

  if (rule.weekday === null) return null;
  const back = (isoWeekday(today) - rule.weekday + 7) % 7;
  const candidate = addDays(today, -back);
  return candidate < rule.startsOn ? null : candidate;
}
